// spec: specs/inventory.md §4
// seed: tests/seed.admin.spec.ts
// inventory · кейс inv-07 (.qa/tests/inventory/) — удаление товара с остатком «ללא מקום», #d17c625a (עבר QA 2026-10-12)
// + #d7b7ec74 (обычное окно без «ייגרעו», без записи «מחיקת מוצר» в журнале):
//   НЕ привязан к месту, только «ללא מקום» → обычное окно «מחיקת מוצר» → удаляется (решение 05.10);
//   ПРИВЯЗАН к месту и есть остаток «ללא מקום» → блок «לא ניתן למחוק…» с местами и «מעבר למפת המחסן» (решение 11.10);
//   гонка: окно открыто для привязанного товара с 0, в это время приход «ללא מקום» → сервер 400 PRODUCT_HAS_PLACE.
// Товары «QA-AUTO-d17c-*-<ts>», места — свободные «ריק» полки, найденные на карте во время прогона (шкафы G/F/E).
// ⚠️ Приёмки оставляют НЕУДАЛЯЕМЫЕ записи «קליטה» в יומן תנועות — здесь 6 (U: 1, C: 2, D: 2, R: 1).
// Уборка — «הסרה מהמקום» и удаление (не привязан → удаляется); места снова «ריק».
// Не запускать одновременно с inventory-lifecycle / order-lifecycle / cart-checkout (общие данные склада).
import { test, expect, Page } from '@playwright/test';
import * as H from './_places';

test.use({ storageState: H.ADMIN });
test.describe.configure({ mode: 'serial' });

const TS = Date.now().toString().slice(-7);
const CABINETS = ['G', 'F', 'E'];
const U = `QA-AUTO-d17c-U-${TS}`; // без места, 3 «ללא מקום»
const C = `QA-AUTO-d17c-C-${TS}`; // 1 место (0 в месте) + «ללא מקום» 1 → 2
const D = `QA-AUTO-d17c-D-${TS}`; // 2 места: 1 в месте + 1 «ללא מקום»
const R = `QA-AUTO-d17c-RN-${TS}`; // гонка «ללא מקום»
const created = new Set<string>();
const used: H.Used = new Map();

async function openBlock(page: Page, p: string) {
  await H.findProduct(page, p);
  await (await H.openRowMenuDelete(page, p)).click();
  const dlg = page.getByRole('dialog');
  await expect(dlg.getByRole('heading', { name: H.BLOCK })).toBeVisible({ timeout: 20_000 });
  await expect(dlg.getByRole('button', { name: 'סגירה' })).toBeVisible();
  await expect(dlg.getByRole('button', { name: 'מעבר למפת המחסן' })).toBeVisible();
  await expect(dlg.getByRole('button', { name: 'מחיקה', exact: true })).toHaveCount(0);
  return dlg;
}

async function closeBlock(page: Page, p: string, qty: number) {
  const dlg = page.getByRole('dialog');
  await dlg.getByRole('button', { name: 'סגירה' }).click();
  await expect(dlg).toHaveCount(0);
  await expect(H.qtyBtn(page, p)).toHaveText(String(qty));
}

test.describe('inventory — מחיקת מוצר עם מלאי «ללא מקום» (#d17c625a)', () => {
  test.afterAll(async ({ browser }) => {
    test.setTimeout(300_000);
    await H.cleanup(browser, created, used);
  });

  test('לא משויך + 3 «ללא מקום» → «מחיקה» → חלון רגיל בלי «ייגרעו»/«החזרה לספק»; ביטול; מחיקה; ביומן אין «מחיקת מוצר» #d17c625a #d7b7ec74 @desktop @data', async ({ page }) => {
    test.setTimeout(180_000);
    await H.createProduct(page, U, `QAD17U${TS}`, created);
    await H.receive(page, U, 3, null);
    await expect(H.row(page, U)).toContainText('ללא מיקום');

    const del = await H.openRowMenuDelete(page, U);
    await expect(del).not.toContainText('יש מלאי במחסן');
    await del.click();
    const dlg = page.getByRole('dialog');
    await H.expectPlainDeleteDialog(dlg, U);
    await dlg.getByRole('button', { name: 'ביטול' }).click();
    await expect(dlg).toHaveCount(0);
    await expect(H.qtyBtn(page, U)).toHaveText('3');

    await (await H.openRowMenuDelete(page, U)).click();
    await H.expectPlainDeleteDialog(dlg, U);
    await H.confirmDelete(page, U, true);
    created.delete(U);

    // журнал: приёмка «ללא מקום» есть, записи об удалении/списании нет (#d7b7ec74)
    await H.openMap(page);
    const expand = page.getByRole('button', { name: 'פתיחת יומן התנועות' });
    if (await expand.isVisible().catch(() => false)) await expand.click();
    await page.getByRole('textbox', { name: 'חיפוש ביומן התנועות' }).fill(U);
    const entry = (kind: string) =>
      page.getByText(kind, { exact: true }).and(page.locator(':not([role="tab"])'))
        .locator(`xpath=ancestor::div[.//*[contains(normalize-space(), "${U}")]][1]`);
    await expect(entry('קליטה')).toHaveCount(1, { timeout: 20_000 });
    await expect(entry('קליטה')).toContainText('ללא מקום');
    await expect(entry('מחיקת מוצר')).toHaveCount(0);
    await expect(page.getByText(/נגרע מהמלאי/)).toHaveCount(0);
  });

  test('משויך למקום + «ללא מקום» → חסימה: «ורשומה עדיין יחידה אחת ללא מקום.», ואחרי עוד יחידה — «ורשומות עדיין 2 ללא מקום.» #d17c625a @desktop @data', async ({ page }) => {
    test.setTimeout(240_000);
    const [pl] = await H.pickEmptyPlaces(page, 1, CABINETS);
    await H.createProduct(page, C, `QAD17C${TS}`, created);
    H.track(used, C, pl);
    await H.bindPlace(page, C, pl); // сначала место
    await H.receive(page, C, 1, null); // затем приход «ללא מקום — לשיוך בהמשך»

    let dlg = await openBlock(page, C);
    await expect(dlg).toContainText(C);
    await expect(dlg).toContainText('משויך למקום במחסן');
    await expect(dlg).toContainText('ורשומה עדיין יחידה אחת ללא מקום.');
    await expect(dlg).not.toContainText('רשומות עדיין 1');
    await expect(dlg.getByRole('listitem').filter({ hasText: pl.code })).toHaveCount(1);
    await closeBlock(page, C, 1);

    await H.receive(page, C, 1, null);
    dlg = await openBlock(page, C);
    await expect(dlg).toContainText('ורשומות עדיין 2 ללא מקום.');
    await expect(dlg.getByRole('listitem').filter({ hasText: pl.code })).toHaveCount(1);
    await closeBlock(page, C, 2);
  });

  test('שני מקומות: יחידה במקום + 1 «ללא מקום» → «משויך ל-2 מקומות במחסן, ורשומה בהם עדיין יחידה אחת, ועוד 1 ללא מקום.», שני המקומות ברשימה #d17c625a @desktop @data', async ({ page }) => {
    test.setTimeout(300_000);
    const [p1, p2] = await H.pickEmptyPlaces(page, 2, CABINETS);
    await H.createProduct(page, D, `QAD17D${TS}`, created);
    H.track(used, D, p1, p2);
    await H.bindPlace(page, D, p1);
    await H.bindPlace(page, D, p2, true);
    await H.receive(page, D, 1, p1.code);
    await H.receive(page, D, 1, null);

    const dlg = await openBlock(page, D);
    await expect(dlg).toContainText('— משויך ל-2 מקומות במחסן, ורשומה בהם עדיין יחידה אחת, ועוד 1 ללא מקום.');
    const items = dlg.getByRole('listitem');
    await expect(items).toHaveCount(2);
    await expect(items.filter({ hasText: p1.code })).toContainText(new RegExp(`${p1.code}\\s*· 1$`));
    await expect(items.filter({ hasText: p2.code })).toHaveCount(1);
    await closeBlock(page, D, 2);
  });

  test('בדיקת שרת: חלון «מחיקת מוצר» פתוח (משויך, 0), בינתיים נקלטה יחידה «ללא מקום» → 400 PRODUCT_HAS_PLACE → חלון החסימה עם «מעבר למפת המחסן», המוצר לא נמחק #d17c625a @desktop @data', async ({ page }) => {
    test.setTimeout(240_000);
    const [pl] = await H.pickEmptyPlaces(page, 1, CABINETS);
    await H.createProduct(page, R, `QAD17RN${TS}`, created);
    H.track(used, R, pl);
    await H.bindPlace(page, R, pl);
    await H.findProduct(page, R);
    await (await H.openRowMenuDelete(page, R)).click();
    const dlg = page.getByRole('dialog');
    await H.expectPlainDeleteDialog(dlg, R);

    const other = await page.context().newPage();
    try {
      await H.receive(other, R, 1, null);
    } finally {
      await other.close();
    }

    const respP = page.waitForResponse((r) => r.url().includes('/rpc/delete_product') && r.request().method() === 'POST');
    await dlg.getByRole('button', { name: 'מחיקה', exact: true }).click();
    const resp = await respP;
    expect(resp.status()).toBe(400);
    expect(await resp.text()).toContain('PRODUCT_HAS_PLACE');
    await expect(dlg.getByRole('heading', { name: H.BLOCK })).toBeVisible({ timeout: 15_000 });
    await expect(dlg.getByRole('button', { name: 'מעבר למפת המחסן' })).toBeVisible();
    await expect(page.getByText(/נמחק\.|הוסר מהקטלוג/).filter({ hasText: R })).toHaveCount(0);
    await page.keyboard.press('Escape');

    await H.expectStock(page, R, 1); // товар не удалён
  });
});
